`parseMyAvail`, `parseOutlook`, `parsePlanner`, and `jsonStringList` are all private top-level functions in `MainActivity.kt:182-217`. They are pure (no Android deps) and ideal for JVM unit tests, but currently untestable because of `private` visibility.

**Blocker:** All five helpers must be made `internal` (or moved to a separate `Parsers.kt` file) before tests can reach them.

**Untested edge cases:**
- Null / missing JSON keys fall back to 0 / empty list
- `JSONArray` with entries that are empty strings
- `parseOutlook` when `inbox` object is absent (`null`)
- `parsePlanner` when `openTitles` key is missing entirely

**Skeleton** (add to `ExampleUnitTest.kt` after refactoring visibility):

```kotlin
class ParserTest {

    // jsonStringList --------------------------------------------------------

    @Test
    fun `jsonStringList returns empty list for null array`() {
        assertEquals(emptyList<String>(), jsonStringList(null))
    }

    @Test
    fun `jsonStringList returns empty list for empty array`() {
        assertEquals(emptyList<String>(), jsonStringList(JSONArray()))
    }

    @Test
    fun `jsonStringList maps all entries`() {
        val arr = JSONArray().apply { put("Alpha"); put("Beta") }
        assertEquals(listOf("Alpha", "Beta"), jsonStringList(arr))
    }

    // parseMyAvail ----------------------------------------------------------

    @Test
    fun `parseMyAvail maps full payload correctly`() {
        val json = JSONObject("""
            {
              "type":"myAvailability-summary",
              "time":"10:30:00",
              "operational":{"count":3,"items":["Op1","Op2","Op3"]},
              "activity":{"count":1,"items":["Act1"]},
              "ooaa":{"count":2,"items":["OOAA1","OOAA2"]},
              "ooaaApprovals":{"count":1,"items":[]},
              "messages":{"unreadChannels":4,"totalUnread":12}
            }
        """)
        val result = parseMyAvail(json)
        assertEquals(3, result.operationalCount)
        assertEquals(1, result.activityCount)
        assertEquals(2, result.ooaaCount)
        assertEquals(1, result.ooaaApprovalsCount)
        assertEquals(4, result.unreadChannels)
        assertEquals(12, result.totalUnread)
        assertEquals(listOf("Op1","Op2","Op3"), result.operationalTitles)
        assertEquals("10:30:00", result.time)
    }

    @Test
    fun `parseMyAvail uses defaults when keys are absent`() {
        val result = parseMyAvail(JSONObject("""{"type":"myAvailability-summary"}"""))
        assertEquals(0, result.operationalCount)
        assertEquals(emptyList<String>(), result.activityTitles)
        assertEquals("", result.time)
    }

    @Test
    fun `parseMyAvail handles missing messages object`() {
        val json = JSONObject("""{"type":"myAvailability-summary","operational":{"count":1,"items":["X"]}}""")
        val result = parseMyAvail(json)
        assertEquals(0, result.unreadChannels)
        assertEquals(0, result.totalUnread)
    }

    // parseOutlook ----------------------------------------------------------

    @Test
    fun `parseOutlook maps full payload correctly`() {
        val json = JSONObject("""
            {
              "inbox":{"unreadCount":5,"recentSenders":["Alice","Bob"]},
              "recentConversations":["Conv1","Conv2"],
              "time":"11:00:00"
            }
        """)
        val result = parseOutlook(json)
        assertEquals(5, result.unreadCount)
        assertEquals(listOf("Alice","Bob"), result.recentSenders)
        assertEquals(listOf("Conv1","Conv2"), result.recentConversations)
    }

    @Test
    fun `parseOutlook uses defaults when inbox is absent`() {
        val result = parseOutlook(JSONObject("""{"time":"12:00:00"}"""))
        assertEquals(0, result.unreadCount)
        assertEquals(emptyList<String>(), result.recentSenders)
    }

    // parsePlanner ----------------------------------------------------------

    @Test
    fun `parsePlanner maps full payload correctly`() {
        val json = JSONObject("""{"totalTasks":10,"openTasks":3,"openTitles":["T1","T2","T3"],"time":"09:00:00"}""")
        val result = parsePlanner(json)
        assertEquals(10, result.totalTasks)
        assertEquals(3, result.openTasks)
        assertEquals(listOf("T1","T2","T3"), result.openTitles)
    }

    @Test
    fun `parsePlanner handles missing openTitles`() {
        val result = parsePlanner(JSONObject("""{"totalTasks":5,"openTasks":2}"""))
        assertEquals(emptyList<String>(), result.openTitles)
    }

    @Test
    fun `parsePlanner handles zero tasks`() {
        val result = parsePlanner(JSONObject("""{"totalTasks":0,"openTasks":0,"openTitles":[]}"""))
        assertEquals(0, result.totalTasks)
        assertEquals(0, result.openTasks)
    }
}
```

