`parseActionItems` at `MainActivity.kt:344` strips markdown fences and parses a JSON array from Claude's response. It is the most critical pure function — a bug here silently corrupts the Dashboard.

**Untested edge cases:**
- Response wrapped in ` ```json ... ``` ` (Claude often does this despite the prompt)
- Empty array `[]` (returns empty list, not an error)
- Extra leading text before `[`
- Missing `priority` field (should default to `"low"`)
- No array brackets at all → should throw
- Completely invalid JSON → should throw

```kotlin
class ParseActionItemsTest {

    @Test
    fun `parses bare JSON array`() {
        val json = """[{"source":"email-personal","subject":"Meeting","action":"Reply","priority":"high"}]"""
        val items = parseActionItems(json)
        assertEquals(1, items.size)
        assertEquals("high", items[0].priority)
        assertEquals("Meeting", items[0].subject)
    }

    @Test
    fun `strips markdown json fence`() {
        val input = "```json\n[{\"source\":\"planner\",\"subject\":\"Task\",\"action\":\"Do it\",\"priority\":\"low\"}]\n```"
        val items = parseActionItems(input)
        assertEquals(1, items.size)
        assertEquals("planner", items[0].source)
    }

    @Test
    fun `strips bare markdown fence`() {
        val input = "```\n[{\"source\":\"planner\",\"subject\":\"Task\",\"action\":\"Do it\",\"priority\":\"medium\"}]\n```"
        val items = parseActionItems(input)
        assertEquals(1, items.size)
    }

    @Test
    fun `returns empty list for empty array`() {
        assertEquals(emptyList<ActionItem>(), parseActionItems("[]"))
    }

    @Test
    fun `missing priority field defaults to low`() {
        val json = """[{"source":"chat","subject":"Hi","action":"Check"}]"""
        val items = parseActionItems(json)
        assertEquals("low", items[0].priority)
    }

    @Test(expected = Exception::class)
    fun `throws when no array brackets present`() {
        parseActionItems("Not JSON at all")
    }

    @Test(expected = Exception::class)
    fun `throws when JSON is invalid`() {
        parseActionItems("[{broken")
    }

    @Test
    fun `handles preamble text before array`() {
        val input = "Sure, here are the items:\n[{\"source\":\"planner\",\"subject\":\"X\",\"action\":\"Y\",\"priority\":\"medium\"}]"
        val items = parseActionItems(input)
        assertEquals(1, items.size)
    }
}
```

