`buildActionsPrompt` at `MainActivity.kt:246` constructs the text sent to the Claude API. An error here means the wrong prompt is sent and the API response is incorrect.

**Untested edge cases:**
- All inputs null → returns blank string (triggers early-exit guard in caller)
- `outlookPersonal` present but `recentConversations` is empty → section must be omitted
- `ooaaApprovalsCount > 0` → section added even without titles
- `unreadChannels == 0` → chat section omitted

```kotlin
class BuildActionsPromptTest {

    @Test
    fun `returns blank when all inputs are null`() {
        val result = buildActionsPrompt(null, null, null, null)
        assertTrue(result.isBlank())
    }

    @Test
    fun `includes personal outlook section when conversations present`() {
        val outlook = OutlookData(unreadCount = 3, recentConversations = listOf("Email A", "Email B"))
        val result = buildActionsPrompt(null, outlook, null, null)
        assertTrue(result.contains("Personal SES Outlook"))
        assertTrue(result.contains("Email A"))
    }

    @Test
    fun `omits personal outlook section when conversations empty`() {
        val outlook = OutlookData(unreadCount = 3, recentConversations = emptyList())
        val result = buildActionsPrompt(null, outlook, null, null)
        assertFalse(result.contains("Personal SES Outlook"))
    }

    @Test
    fun `includes dbo ops section separately from personal`() {
        val dbo = OutlookData(unreadCount = 1, recentConversations = listOf("DBO email"))
        val result = buildActionsPrompt(null, null, dbo, null)
        assertTrue(result.contains("DBO Ops"))
        assertTrue(result.contains("DBO email"))
    }

    @Test
    fun `includes ooaaApprovals section when count is positive`() {
        val myAvail = MyAvailData(ooaaApprovalsCount = 2)
        val result = buildActionsPrompt(myAvail, null, null, null)
        assertTrue(result.contains("OOAA approvals pending Carl's action: 2"))
    }

    @Test
    fun `omits chat section when unreadChannels is zero`() {
        val myAvail = MyAvailData(unreadChannels = 0, totalUnread = 0)
        val result = buildActionsPrompt(myAvail, null, null, null)
        assertFalse(result.contains("myAvailability chat"))
    }

    @Test
    fun `includes planner section with open titles`() {
        val planner = PlannerData(totalTasks = 5, openTasks = 2, openTitles = listOf("Fix roof", "Order supplies"))
        val result = buildActionsPrompt(null, null, null, planner)
        assertTrue(result.contains("Planner tasks"))
        assertTrue(result.contains("Fix roof"))
    }

    @Test
    fun `omits planner section when open titles empty`() {
        val planner = PlannerData(totalTasks = 5, openTasks = 0, openTitles = emptyList())
        val result = buildActionsPrompt(null, null, null, planner)
        assertFalse(result.contains("Planner tasks"))
    }
}
