`ActionItem.dismissKey()` at `MainActivity.kt:131` is the key used to track dismissed items. A bug here causes items to never dismiss or to dismiss incorrectly.

```kotlin
class ActionItemDismissKeyTest {

    @Test
    fun `dismissKey concatenates fields with pipe separator`() {
        val item = ActionItem(source = "email-personal", subject = "Meeting", action = "Reply", priority = "high")
        assertEquals("email-personal|Meeting|Reply", item.dismissKey())
    }

    @Test
    fun `two items with same source subject action have same dismiss key`() {
        val a = ActionItem("chat", "Alert", "Check", "low")
        val b = ActionItem("chat", "Alert", "Check", "medium")
        assertEquals(a.dismissKey(), b.dismissKey())
    }

    @Test
    fun `two items differing in any field have different dismiss keys`() {
        val base = ActionItem("chat", "Alert", "Check", "low")
        assertNotEquals(base.dismissKey(), base.copy(source = "planner").dismissKey())
        assertNotEquals(base.dismissKey(), base.copy(subject = "Other").dismissKey())
        assertNotEquals(base.dismissKey(), base.copy(action = "Ignore").dismissKey())
    }
}
```

