`ScrapeBridge.reportData()` at `MainActivity.kt:152` silently swallows all exceptions. The unknown-type branch and the malformed-JSON branch are completely unverified.

```kotlin
class ScrapeBridgeTest {

    private fun resetState() {
        myAvailState.value = null
        outlookPersonalState.value = null
        outlookDboOpsState.value = null
        plannerState.value = null
    }

    @Before fun setUp() = resetState()

    @Test
    fun `malformed JSON does not crash and leaves state unchanged`() {
        val bridge = ScrapeBridge()
        bridge.reportData("{not valid json}")
        // State must remain null — no crash
        assertNull(myAvailState.value)
    }

    @Test
    fun `unknown type is silently ignored`() {
        val bridge = ScrapeBridge()
        bridge.reportData("""{"type":"unknown-future-type","data":42}""")
        assertNull(myAvailState.value)
        assertNull(outlookPersonalState.value)
    }

    @Test
    fun `myAvailability-summary type updates myAvailState`() {
        val bridge = ScrapeBridge()
        val json = """
            {"type":"myAvailability-summary","time":"10:00:00",
             "operational":{"count":1,"items":["Op1"]},
             "activity":{"count":0,"items":[]},
             "ooaa":{"count":0,"items":[]},
             "ooaaApprovals":{"count":0,"items":[]},
             "messages":{"unreadChannels":0,"totalUnread":0}}
        """.trimIndent()
        bridge.reportData(json)
        // Handler posts to main looper — advance it in instrumented test or use IdlingResource
        assertNotNull(myAvailState.value)
        assertEquals(1, myAvailState.value!!.operationalCount)
    }

    @Test
    fun `outlook-summary with cloud·microsoft host routes to dboOps state`() {
        val bridge = ScrapeBridge()
        val json = """
            {"type":"outlook-summary","host":"outlook.cloud.microsoft",
             "inbox":{"unreadCount":2,"recentSenders":[]},
             "recentConversations":[],"time":"09:00:00"}
        """.trimIndent()
        bridge.reportData(json)
        assertNotNull(outlookDboOpsState.value)
        assertNull(outlookPersonalState.value)
    }

    @Test
    fun `outlook-summary without cloud·microsoft host routes to personal state`() {
        val bridge = ScrapeBridge()
        val json = """
            {"type":"outlook-summary","host":"outlook.office.com",
             "inbox":{"unreadCount":7,"recentSenders":[]},
             "recentConversations":[],"time":"09:00:00"}
        """.trimIndent()
        bridge.reportData(json)
        assertNotNull(outlookPersonalState.value)
        assertNull(outlookDboOpsState.value)
    }
}
```

> **Note:** `ScrapeBridge.reportData()` posts work via `Handler(Looper.getMainLooper())`, so the assertions above require either `ShadowLooper.runMainLooperToNextTask()` (Robolectric) or an instrumented test with `IdlingResource`. The skeleton above shows the intent; the test runner setup is needed before it can pass.

