        outlookPersonalState.value = null
        outlookDboOpsState.value = null
        plannerState.value = null

        triggerActionItemsGeneration(context)

        assertEquals(
            "No data to analyse yet — refresh sources first.",
            actionItemsError.value
        )
    }
}
